head.script:
scwin.onpageload = function() {

};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_2').getAttribute('aria-expanded') == 'false';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_2').getAttribute('aria-labelledby') === null;
	}			
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_2_button').getAttribute('aria-labelledby') === null;
	}		
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_2_button').getAttribute('aria-controls') === null;
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
		WebSquare.wUnit.addCommand("pause", "500");				
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
